69	export function transformMCPToolsToAnthropic(tools: MCPTool[]): Anthropic.Tool[] {
70	  return tools.map((tool) => {
71	    // Remove $schema field if present to prevent provider errors
72	    const { $schema: _$schema, ...cleanSchema } = tool.inputSchema;
73	    return {
74	      name: tool.name,
75	      description: tool.description,
76	      input_schema: {
77	        type: 'object',
78	        ...cleanSchema,
79	      },
80	    };
81	  });
82	}
