118	export async function transformMCPConfigToClaudeCode(
119	  config: MCPConfig,
120	): Promise<Record<string, ClaudeCodeMcpServerConfig>> {
121	  const serverConfigs = config.servers ?? [];
122	  if (config.server) {
123	    serverConfigs.push(config.server);
124	  }
125	
126	  const servers = await Promise.all(
127	    serverConfigs.map((server) => transformMCPServerConfigToClaudeCode(server)),
128	  );
129	
130	  return servers.reduce<Record<string, ClaudeCodeMcpServerConfig>>((acc, transformed) => {
131	    const [key, out] = transformed;
132	    acc[key] = out;
133	    return acc;
134	  }, {});
135	}
