137	async function transformMCPServerConfigToClaudeCode(
138	  config: MCPServerConfig,
139	): Promise<[string, ClaudeCodeMcpServerConfig]> {
140	  const key = config.name ?? config.url ?? config.command ?? 'default';
141	  let out: ClaudeCodeMcpServerConfig | undefined;
142	
143	  if (config.url) {
144	    // Render environment variables in auth config
145	    const renderedConfig = renderAuthVars(config);
146	
147	    // Handle OAuth token fetching if needed
148	    let oauthToken: string | undefined;
149	    if (requiresAsyncAuth(renderedConfig) && renderedConfig.auth?.type === 'oauth') {
150	      oauthToken = await getOAuthToken(
151	        renderedConfig.auth as MCPOAuthClientCredentialsAuth | MCPOAuthPasswordAuth,
152	      );
153	    }
154	
155	    // Apply query params for api_key with query placement
156	    const queryParams = getAuthQueryParams(renderedConfig);
157	    const serverUrl = applyQueryParams(config.url, queryParams);
158	
159	    out = {
160	      type: 'http',
161	      url: serverUrl,
162	      headers: { ...(config.headers ?? {}), ...getAuthHeaders(renderedConfig, oauthToken) },
163	    };
164	  } else if (config.command && config.args) {
165	    out = { type: 'stdio', command: config.command, args: config.args };
166	  } else if (config.path) {
167	    const isPy = config.path.endsWith('.py');
168	    const command = isPy ? (process.platform === 'win32' ? 'python' : 'python3') : process.execPath;
169	    out = { type: 'stdio', command, args: [config.path] };
170	  } else {
171	    throw new Error('MCP configuration cannot be converted to Claude Agent SDK MCP server config');
172	  }
173	
174	  return [key, out];
175	}
