62	  ): Promise<ProviderResponse> {
63	    try {
64	      // Ensure initialization is complete
65	      await this.initializationPromise;
66	
67	      // Parse the prompt as JSON to extract tool call information
68	      let toolCallData: any;
69	      try {
70	        const rawToolCall = context?.vars?.prompt ?? prompt;
