77	      }
78	
79	      // Extract tool name from various possible fields
80	      const toolName =
81	        toolCallData.tool ||
82	        toolCallData.toolName ||
83	        toolCallData.function ||
84	        toolCallData.functionName ||
85	        toolCallData.name;
86	
87	      if (!toolName || typeof toolName !== 'string') {
88	        return {
89	          error:
90	            'No tool name found in JSON payload. Expected format: {"tool": "function_name", "args": {...}}',
91	        };
92	      }
93	
94	      // Extract tool arguments from various possible fields
95	      let toolArgs =
96	        toolCallData.args ||
97	        toolCallData.arguments ||
98	        toolCallData.params ||
99	        toolCallData.parameters ||
100	        {};
