102	      // Ensure toolArgs is an object
103	      if (typeof toolArgs !== 'object' || toolArgs === null || Array.isArray(toolArgs)) {
104	        toolArgs = {};
105	      }
106	
107	      // Merge with default args
108	      const finalArgs = {
109	        ...this.defaultArgs,
110	        ...toolArgs,
111	      };
112	
113	      logger.debug(`MCP Provider calling tool ${toolName} with args: ${JSON.stringify(finalArgs)}`);
114	
115	      // Call the MCP tool
116	      const result = await this.mcpClient.callTool(toolName, finalArgs);
117	
118	      if (result.error) {
119	        return {
120	          error: `MCP tool error: ${result.error}`,
121	          raw: result,
122	        };
123	      }
124	
125	      return {
126	        output: result.content,
127	        raw: result,
128	        metadata: {
129	          toolName,
130	          toolArgs: finalArgs,
131	          originalPayload: toolCallData,
132	        },
133	      };
134	    } catch (error) {
135	      const errorMessage = error instanceof Error ? error.message : String(error);
136	      logger.error(`MCP Provider error: ${errorMessage}`);
137	      return {
138	        error: `MCP Provider error: ${errorMessage}`,
139	      };
