/**
 * Normalizes an arbitrary transform return value into a {@link ProviderResponse}.
 *
 * If the value is already a ProviderResponse (a non-null, non-array object that
 * contains an `output` or `error` property), it is returned unchanged. Otherwise
 * the value is wrapped as `{ output: value }`.
 *
 * This lets response transforms return either a full ProviderResponse or a bare
 * value (string, number, object, etc.) that should become the `output`.
 */
export function normalizeResponseTransformResult(value: unknown): ProviderResponse {
  if (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value) &&
    ('output' in value || 'error' in value)
  ) {
    return value as ProviderResponse;
  }
  return { output: value };
}
