import cliState from '../cliState';
import { importModule } from '../esm';
import { isJavascriptFile } from '../util/fileExtensions';

/**
 * Parses a `file://` transform reference into its filename and optional named export.
 *
 * The `file://` prefix is stripped, then the reference is split on the LAST colon to
 * separate the filename from an optional named export (`functionName`). A colon is only
 * treated as a named-export separator when the portion before it is recognized as a
 * JavaScript file and the portion after it is a non-empty function name. This ensures
 * Windows drive-letter colons (e.g. `C:\path\parser.js`) are not mistaken for a
 * named-export separator.
 *
 * @example
 * parseFileTransformReference('file://path/to/parser.js:parse')
 * // => { filename: 'path/to/parser.js', functionName: 'parse' }
 * parseFileTransformReference('file://C:\\path\\parser.js')
 * // => { filename: 'C:\\path\\parser.js' }
 * parseFileTransformReference('file://C:\\path\\parser.js:parse')
 * // => { filename: 'C:\\path\\parser.js', functionName: 'parse' }
 */
export function parseFileTransformReference(reference: string): {
  filename: string;
  functionName?: string;
} {
  const withoutPrefix = reference.startsWith('file://')
    ? reference.slice('file://'.length)
    : reference;

  const lastColon = withoutPrefix.lastIndexOf(':');
  if (lastColon !== -1) {
    const before = withoutPrefix.slice(0, lastColon);
    const after = withoutPrefix.slice(lastColon + 1);
    if (before && after && isJavascriptFile(before)) {
      return { filename: before, functionName: after };
    }
  }

  return { filename: withoutPrefix };
}

/**
 * Pre-loads a transform from a `file://` reference by resolving the filename relative to
 * `cliState.basePath` and importing the module.
 *
 * If the resolved module is a function, it is returned. If it is not a function, an error
 * is thrown. For non-file transforms (functions or plain string expressions), the input is
 * returned unchanged.
 */
export async function loadTransformModule(
  transform: string | Function | undefined,
): Promise<string | Function | undefined> {
  if (!transform) {
    return transform;
  }
  if (typeof transform === 'function') {
    return transform;
  }
  if (typeof transform === 'string' && transform.startsWith('file://')) {
    const { filename, functionName } = parseFileTransformReference(transform);
    const requiredModule = await importModule(
      path.resolve(cliState.basePath || '', filename),
      functionName,
    );
    if (typeof requiredModule === 'function') {
      return requiredModule;
    }
    throw new Error(
      `Transform module malformed: ${filename} must export a function or have a default export as a function`,
    );
  }
  // For string expressions, return as-is
  return transform;
}
